SET NOCOUNT ON; SET XACT_ABORT ON; SET ANSI_NULLS ON; SET QUOTED_IDENTIFIER ON; SET ANSI_PADDING ON; SET ANSI_WARNINGS ON; SET ARITHABORT ON; SET CONCAT_NULL_YIELDS_NULL ON; SET NUMERIC_ROUNDABORT OFF;
DECLARE @BaseEsperada sysname=N'FractalesAcademy';
IF DB_NAME()<>@BaseEsperada OR DB_NAME() IN('master','model','msdb','tempdb') THROW 54500,'Confirma servidor y @BaseEsperada.',1;
IF HAS_PERMS_BY_NAME(DB_NAME(),'DATABASE','VIEW DEFINITION')<>1 THROW 54501,'Se requiere VIEW DEFINITION para inspeccionar dependencias.',1;
IF OBJECT_ID('dbo.Control_Migracion_V4') IS NULL THROW 54501,'Esquema de origen incorrecto.',1;
BEGIN TRY BEGIN TRAN;
 IF NOT EXISTS(SELECT 1 FROM dbo.Control_Migracion_V4 WITH(UPDLOCK,HOLDLOCK) WHERE Script='V45_01_PREPARAR')
 BEGIN
IF NOT EXISTS(SELECT 1 FROM dbo.Control_Migracion_V4 WHERE Script='V44_04_RETIRAR') THROW 54501,'Completar V4.4 primero.',1;
IF EXISTS(SELECT 1 FROM sys.foreign_keys WHERE is_disabled=1 OR is_not_trusted=1) THROW 54501,'Relaciones no confiables.',1;
IF OBJECT_ID('dbo.MIGRACION_INTEGRIDAD_V45') IS NOT NULL THROW 54501,'Existe estructura parcial sin marcador.',1;
CREATE TABLE dbo.MIGRACION_INTEGRIDAD_V45(TABLA sysname NOT NULL,CLAVE nvarchar(400) NOT NULL,HUELLA varbinary(32) NOT NULL,CONSTRAINT PK_MIGRACION_INTEGRIDAD_V45 PRIMARY KEY(TABLA,CLAVE));
