WHEN j.[key] COLLATE Latin1_General_100_BIN2=N''Nueva_Clave'' COLLATE Latin1_General_100_BIN2 THEN N''NUEVA_CLAVE'' ELSE j.[key] END COLLATE Latin1_General_100_BIN2) FROM OPENJSON(@json) j;
 RETURN CASE WHEN @array=1 THEN ''['' ELSE ''{'' END+COALESCE(@result,'''')+CASE WHEN @array=1 THEN '']'' ELSE ''}'' END;
END;';
INSERT dbo.MIGRACION_INTEGRIDAD_V45(TABLA,CLAVE,HUELLA) SELECT N'ALUMNO',(SELECT r.[DNI_Alu] AS [DNI_ALUMNO] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES),HASHBYTES('SHA2_256',(SELECT r.[DNI_Alu] AS [DNI_ALUMNO],r.[Nomb_Alu] AS [NOMBRE_COMPLETO],r.[Correo_Alu] AS [CORREO],r.[Fech_Nac] AS [FECHA_NACIMIENTO],r.[Cel_Alu] AS [CELULAR],r.[Dir_Alu] AS [DIRECCION],r.[Nomb_Apoderado] AS [NOMBRE_APODERADO],r.[DNI_Apoderado] AS [DNI_APODERADO],r.[Cel_Apoderado] AS [CELULAR_APODERADO],r.[Correo_Apoderado] AS [CORREO_APODERADO],r.[PARENTESCO_Cod_Paren] AS [ID_PARENTESCO],r.[CARRERA_Cod_Carrera] AS [ID_CARRERA],r.[Es_Prueba] AS [ES_PRUEBA] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)) FROM dbo.[ALUMNO] r WITH(TABLOCKX,HOLDLOCK);
