INSERT dbo.MIGRACION_INTEGRIDAD_V45(TABLA,CLAVE,HUELLA) SELECT N'AUDITORIA_SISTEMA',(SELECT r.[Id] AS [ID] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES),HASHBYTES('SHA2_256',(SELECT r.[Id] AS [ID],CASE WHEN r.[Entidad]=N'Alumno_Estado_V41' THEN N'ESTADO_ALUMNO' WHEN r.[Entidad]=N'Auditoria_V4' THEN N'AUDITORIA_SISTEMA' WHEN r.[Entidad]=N'Aula' THEN N'AULA' WHEN r.[Entidad]=N'Ciclo' THEN N'CICLO' WHEN r.[Entidad]=N'Contacto_Verificado_V41' THEN N'CONTACTO_VERIFICADO' WHEN r.[Entidad]=N'Control_Migracion_V4' THEN N'CONTROL_MIGRACION' WHEN r.[Entidad]=N'Cuenta_Codigo_V41' THEN N'CODIGO_CUENTA' WHEN r.[Entidad]=N'CURSOS' THEN N'CURSO' WHEN r.[Entidad]=N'Docente' THEN N'DOCENTE' WHEN r.[Entidad]=N'Docente_Asignatura' THEN N'CURSO_DOCENTE' WHEN r.[Entidad]=N'ESTADO_EXAMEN_GRUPO' THEN N'ESTADO_SIMULACRO' WHEN r.[Entidad]=N'Examen' THEN N'SIMULACRO' WHEN r.[Entidad]=N'Examen_Grupo' THEN N'SIMULACRO_HORARIO' WHEN r.[Entidad]=N'Grupo' THEN N'HORARIO_ACADEMICO' WHEN r.[Entidad]=N'Horario' THEN N'BLOQUE_HORARIO' WHEN r.[Entidad]=N'Linea_Base_V4' THEN N'LINEA_BASE_MIGRACION' WHEN r.[Entidad]=N'Nota_Estado_V41' THEN N'ESTADO_RESULTADO' WHEN r.[Entidad]=N'Nota_Examen' THEN N'RESULTADO_SIMULACRO' WHEN r.[Entidad]=N'Pago' THEN N'PAGO' WHEN r.[Entidad]=N'Programa' THEN N'PROGRAMA' WHEN r.[Entidad]=N'Solicitud_Contacto_V41' THEN N'SOLICITUD_CONTACTO' WHEN r.[Entidad]=N'Turno' THEN N'TURNO' WHEN r.[Entidad]=N'Usuario' THEN N'USUARIO' WHEN r.[Entidad]=N'Usuario_Seguridad_V41' THEN N'SEGURIDAD_USUARIO' ELSE r.[Entidad] END AS [ENTIDAD],r.[Codigo] AS [ID_REGISTRO],r.[Accion] AS [ACCION],dbo.FN_V45_NORMALIZAR_JSON(r.[Anterior]) AS [DATOS_ANTERIORES],dbo.FN_V45_NORMALIZAR_JSON(r.[Nuevo]) AS [DATOS_NUEVOS],r.[Usuario_Cod_Usuario] AS [ID_USUARIO_RESPONSABLE],r.[Motivo] AS [MOTIVO],r.[Fecha] AS [FECHA_EVENTO] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)) FROM dbo.[Auditoria_V4] r WITH(TABLOCKX,HOLDLOCK);
