INSERT dbo.MIGRACION_INTEGRIDAD_V45(TABLA,CLAVE,HUELLA) SELECT N'TIPO_BLOQUE',(SELECT r.[Cod_Tipo] AS [ID_TIPO_BLOQUE] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES),HASHBYTES('SHA2_256',(SELECT r.[Cod_Tipo] AS [ID_TIPO_BLOQUE],r.[Nomb_Tipo] AS [NOMBRE_TIPO] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)) FROM dbo.[TIPO_BLOQUE] r WITH(TABLOCKX,HOLDLOCK);
INSERT dbo.MIGRACION_INTEGRIDAD_V45(TABLA,CLAVE,HUELLA) SELECT N'TURNO',(SELECT r.[Cod_Turno] AS [ID_TURNO] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES),HASHBYTES('SHA2_256',(SELECT r.[Cod_Turno] AS [ID_TURNO],r.[Nomb_Turno] AS [NOMBRE_TURNO],r.[Hr_Inicio] AS [HORA_INICIO],r.[Hr_Fin] AS [HORA_FIN] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)) FROM dbo.[Turno] r WITH(TABLOCKX,HOLDLOCK);
INSERT dbo.MIGRACION_INTEGRIDAD_V45(TABLA,CLAVE,HUELLA) SELECT N'USUARIO',(SELECT r.[Cod_Usuario] AS [ID_USUARIO] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES),HASHBYTES('SHA2_256',(SELECT r.[Cod_Usuario] AS [ID_USUARIO],r.[Nomb_Usuario] AS [NOMBRE_USUARIO],r.[Clave_Hash] AS [CLAVE_HASH],r.[ROL_Cod_Rol] AS [ID_ROL],r.[Activo] AS [ACTIVO],r.[Debe_Cambiar_Clave] AS [DEBE_CAMBIAR_CLAVE],r.[ALUMNO_DNI_Alu] AS [DNI_ALUMNO],r.[Correo_Recuperacion] AS [CORREO_RECUPERACION],r.[Correo_Verificado] AS [CORREO_VERIFICADO] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)) FROM dbo.[Usuario] r WITH(TABLOCKX,HOLDLOCK);
INSERT dbo.MIGRACION_INTEGRIDAD_V45(TABLA,CLAVE,HUELLA) SELECT N'SEGURIDAD_USUARIO',(SELECT r.[Usuario_Cod_Usuario] AS [ID_USUARIO_RESPONSABLE] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES),HASHBYTES('SHA2_256',(SELECT r.[Usuario_Cod_Usuario] AS [ID_USUARIO_RESPONSABLE],r.[Version_Sesion] AS [VERSION_SESION],r.[Activacion_Requerida] AS [ACTIVACION_REQUERIDA] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)) FROM dbo.[Usuario_Seguridad_V41] r WITH(TABLOCKX,HOLDLOCK);

 INSERT dbo.Control_Migracion_V4(Script) VALUES('V45_01_PREPARAR');
 END; COMMIT;
END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; THROW; END CATCH;
